def check_protocol(value: Any, origin_type: Any, args: tuple[Any, ...],
    memo: TypeCheckMemo) -> None:
    """
    Check if the given value satisfies the given protocol.

    A value satisfies a protocol if it has all the required attributes and methods
    with compatible signatures.
    """
    if not hasattr(origin_type, "_is_protocol") or not origin_type._is_protocol:
        raise TypeCheckError(f"{qualified_name(origin_type)} is not a Protocol")

    # Get protocol attributes (excluding dunder methods)
    protocol_attrs = {
        name for name in dir(origin_type) 
        if not name.startswith("_") or name in BINARY_MAGIC_METHODS
    }

    # Skip some special attributes that shouldn't be checked
    protocol_attrs -= {"__annotations__", "__dict__", "__slots__", "__weakref__", 
                      "__parameters__", "__orig_bases__", "__origin__", "__args__"}

    # Check each attribute
    for attr_name in protocol_attrs:
        if not hasattr(value, attr_name):
            raise TypeCheckError(f"does not have required attribute '{attr_name}'")

        # Get the attribute from the protocol
        proto_attr = getattr(origin_type, attr_name)

        # If it's a method, check signature compatibility
        if callable(proto_attr) and not isinstance(proto_attr, type):
            try:
                check_signature_compatible(value if isclass(value) else type(value), 
                                          origin_type, attr_name)
            except TypeCheckError as exc:
                exc.append_path_element(f"method '{attr_name}'")
                raise

